svg.script:
const upload = document.getElementById('upload');
const fileInput = document.getElementById('file');
let resultTab;
let newTabForSelection = false;
let choosingFile = false;

function finishSelection() {
  choosingFile = false;
  fileInput.value = '';
  if (newTabForSelection && resultTab && !resultTab.closed) {
    resultTab.close();
    resultTab = null;
  }
  newTabForSelection = false;
}

upload.addEventListener('click', () => {
  if (choosingFile) return;
  choosingFile = true;
  fileInput.click();
});

fileInput.addEventListener('change', () => {
  const file = fileInput.files && fileInput.files[0];
  if (!file) {
    finishSelection();
    return;
  }

  const objectUrl = URL.createObjectURL(file);
  try {
    if (!resultTab || resultTab.closed) {
      resultTab = window.open('about:blank', '_blank');
      newTabForSelection = true;
    } else {
      resultTab.focus();
    }
    if (!resultTab) {
      newTabForSelection = false;
      URL.revokeObjectURL(objectUrl);
      window.alert('Allow pop-ups for this page, then upload the file again.');
      return;
    }
    const tab = resultTab;
    if (!tab.__htmlRunnerReady) {
      tab.document.open();
      tab.document.write('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HTML file</title><style>html,body,iframe{width:100%;height:100%;margin:0;border:0;display:block}</style></head><body><iframe id="document"></iframe><script>window.addEventListener("pagehide",function(){if(window.opener&&window.__htmlObjectUrl)window.opener.URL.revokeObjectURL(window.__htmlObjectUrl)})<\/script></body></html>');
      tab.document.close();
      tab.__htmlRunnerReady = true;
    }
    const frame = tab.document.getElementById('document');
    const previousUrl = tab.__htmlObjectUrl;
    tab.__htmlObjectUrl = objectUrl;
    tab.document.title = file.name;
    if (previousUrl) {
      frame.addEventListener('load', () => {
        if (!tab.closed) frame.src = objectUrl;
      }, { once: true });
      frame.src = 'about:blank';
      URL.revokeObjectURL(previousUrl);
    } else {
      frame.src = objectUrl;
    }
    newTabForSelection = false;
  } catch (error) {
    URL.revokeObjectURL(objectUrl);
    if (resultTab && !resultTab.closed && newTabForSelection) resultTab.close();
    if (newTabForSelection) resultTab = null;
    newTabForSelection = false;
    window.alert('This browser could not open the selected file.');
  } finally {
    choosingFile = false;
    fileInput.value = '';
  }
});

fileInput.addEventListener('cancel', finishSelection);
